const description: { en: string; ja: string } = {"en":"Fill the round sparrow and leave fine white lines between its feathers. Join compass arcs to make four solid curled bands, with shallower bands above and below and deeper bands at the sides.","ja":"丸い雀を塗り、羽の間に細い白線を残します。円弧をつないで四つの環を塗ります。上下の環を浅く、左右の環を深くします。"};

export default construction;
